fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    // If lower bound is greater than upper bound, return vector of max_val
    if min_val > max_val {
        return vec![max_val; arr.len()];
    }
    
    // Otherwise, clip each element to the inclusive range [min_val, max_val]
    arr.iter()
        .map(|&x| {
            if x < min_val {
                min_val
            } else if x > max_val {
                max_val
            } else {
                x
            }
        })
        .collect()
}